/*selectSpecialLogicInfo*/ SELECT DECODE(B.PROCESS_TYPE, '2', 'KRKORE0068', B.BUYER) AS BUYER2, A.SELLER AS SELLER, B.REF_IF_NO AS REF_IF_NO, A.ADD_USER_ID AS ADD_USER_ID, A.AGENT AS AGENT, CASE WHEN A.BUYER = 'KRDOOS0004' AND ( B.LEGACY_PO_NO IS NULL OR LENGTH(TRIM(B.LEGACY_PO_NO) ) < 9) THEN '' --두산중공업 서울 사무소 인터페이스 건이 아니면 default url을 사용 --김지현 20141114
WHEN ( LENGTH(C.EXP_ADD_USER_ID) != 0 AND C.EXP_TR = 'Y') --두가지 조건을 모두 쓰는 경우 THEN CASE WHEN (C.EXP_ADD_USER_ID != A.ADD_USER_ID AND B.PROCESS_TYPE !='2') THEN C.RPT_URL ELSE '' END WHEN ( LENGTH(C.EXP_ADD_USER_ID) != 0 ) --ADD_USER_ID제외만 있는경우 THEN CASE WHEN (C.EXP_ADD_USER_ID != A.ADD_USER_ID) THEN C.RPT_URL ELSE '' END WHEN ( C.EXP_TR = 'Y') --TR거래 제외만 있는 경우 THEN CASE WHEN (B.PROCESS_TYPE !='2') THEN C.RPT_URL ELSE '' END ELSE C.RPT_URL --아부 조건이 없으면 END AS RPT_URL -- 고객사 입장에서의 특수로직 해당사항이 없으면 url 결과가 없으므로 default url을 사용 , CASE WHEN ( LENGTH(E.EXP_ADD_USER_ID) != 0 AND E.EXP_TR = 'Y') --두가지 조건을 모두 쓰는 경우 THEN CASE WHEN (E.EXP_ADD_USER_ID != A.ADD_USER_ID AND B.PROCESS_TYPE !='2') THEN E.RPT_URL ELSE '' END WHEN ( LENGTH(E.EXP_ADD_USER_ID) != 0 ) --ADD_USER_ID제외만 있는경우 THEN CASE WHEN (E.EXP_ADD_USER_ID != A.ADD_USER_ID) THEN E.RPT_URL ELSE '' END WHEN ( E.EXP_TR = 'Y') --TR거래 제외만 있는 경우 THEN CASE WHEN (B.PROCESS_TYPE !='2') THEN E.RPT_URL ELSE '' END ELSE E.RPT_URL --아무 조건이 없으면 END AS AGENT_RPT_URL -- 협력사입장에서의 발주서, 특수로직 해당사항이 없으면 url 결과가 없으므로 default url을 사용
FROM ICOMPOHD A, ICOMPODT B , ( SELECT --고객사의 발주서 리포트 정보 X.SLG_NAME , Y.COM_CODE BUYER , Y.COL01_DATA RPT_URL , NVL(Y.COL02_DATA, 'N') EXP_TR --Y이면 TR거래 아닌 조건 , NVL(Y.COL03_DATA, '') EXP_ADD_USER_ID --제외 USER_ID FROM BNTSLGDEF X, BNTSLGIMP Y WHERE X.SLG_ID = Y.SLG_ID AND X.SLG_ID = 'P07-0000005' AND Y.COM_CODE = #{st_buyer} AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN X.OPEN_DATE AND X.CLOSE_DATE AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN Y.OPEN_DATE AND Y.CLOSE_DATE ) C , ( --협력사의 발주서 리포트 정보 SELECT Y.COM_CODE BUYER , Y.COL01_DATA RPT_URL , NVL(Y.COL02_DATA, 'N') EXP_TR --Y이면 TR거래 아닌 조건 , NVL(Y.COL03_DATA, '') EXP_ADD_USER_ID --제외 USER_ID FROM BNTSLGDEF X , BNTSLGIMP Y WHERE X.SLG_ID = Y.SLG_ID AND X.SLG_ID = 'P06-0000025' AND Y.COM_CODE = #{st_buyer} /**P*/ --param buyer com_code AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN X.OPEN_DATE AND X.CLOSE_DATE AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN Y.OPEN_DATE AND Y.CLOSE_DATE ) E WHERE A.BUYER = #{st_buyer} AND A.PO_NO = #{st_po_no} AND A.BUYER = B.BUYER AND A.PO_NO = B.PO_NO AND A.BUYER = C.BUYER(+) AND A.BUYER = E.BUYER(+) AND ROWNUM <= 1
